from pathlib import Path
p=Path(__file__).resolve().parents[1]/'app'/'src'/'main'/'assets'/'index.html'
s=p.read_text(encoding='utf-8')
if 'living-dex-journey" content="1.7"' not in s:s=s.replace('</head>','<meta name="living-dex-journey" content="1.7"/>\n</head>',1)
css=r'''
/* Journey 1.7 */
.game-progress-ring{position:absolute;right:14px;bottom:62px;width:58px;height:58px;border-radius:50%;display:grid;place-items:center;background:conic-gradient(#66e0ad var(--gp),rgba(255,255,255,.07) 0);box-shadow:0 8px 25px rgba(0,0,0,.28)}.game-progress-ring:after{content:"";position:absolute;inset:6px;border-radius:50%;background:#0b1a2b}.game-progress-ring b,.game-progress-ring small{position:relative;z-index:1}.game-progress-ring b{font-size:12px}.game-progress-ring small{font-size:7px;color:#91a7bd}.game-progress-meta{position:absolute;right:78px;bottom:72px;text-align:right;font-size:9px;color:#9eb2c7}.game-progress-meta strong{display:block;color:#eaf8ff;font-size:10px}.mnav-item[data-view="missing"]{display:none!important}.mobile-nav{grid-template-columns:repeat(4,1fr)!important}.journey-launch{margin-top:12px}.journey-shell{position:fixed;inset:0;z-index:8000;background:#07111f;color:#f5f9ff;overflow:auto;padding:calc(18px + env(safe-area-inset-top)) 16px calc(28px + env(safe-area-inset-bottom));animation:premiumViewIn .25s ease}.journey-top{max-width:900px;margin:auto;display:flex;justify-content:space-between;align-items:center;gap:12px}.journey-tabs{max-width:900px;margin:18px auto;display:grid;grid-template-columns:repeat(3,1fr);gap:7px;padding:5px;background:rgba(255,255,255,.035);border:1px solid rgba(148,180,215,.12);border-radius:17px}.journey-tabs button{border:0;border-radius:12px;padding:11px 7px;background:transparent;color:#93a8c0;font-weight:800}.journey-tabs button.active{background:rgba(79,181,255,.14);color:#eaf8ff}.journey-body{max-width:900px;margin:auto}.journey-hero{padding:20px;border:1px solid rgba(148,180,215,.13);border-radius:24px;background:linear-gradient(145deg,rgba(18,40,65,.96),rgba(10,23,40,.98));margin-bottom:14px}.route-list{display:grid;gap:8px}.route-step{display:grid;grid-template-columns:38px 1fr auto;gap:10px;align-items:center;padding:12px;border:1px solid rgba(148,180,215,.11);border-radius:16px;background:rgba(255,255,255,.025)}.route-step .num{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;background:rgba(79,181,255,.12);font-weight:900}.route-step.done{opacity:.55}.route-step.done .num{background:rgba(102,224,173,.15)}.route-step h4{margin:0 0 3px;font-size:12px}.route-step p{margin:0;color:#8fa5bc;font-size:9px}.route-check{width:28px;height:28px;border-radius:9px;border:1px solid rgba(148,180,215,.16);background:rgba(255,255,255,.03);color:#dff}.team-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.team-poke{padding:12px;text-align:center;border-radius:18px;border:1px solid rgba(148,180,215,.11);background:rgba(255,255,255,.025)}.team-poke img{width:72px;height:72px;object-fit:contain}.team-poke b{display:block;font-size:10px}.starter-row,.phase-row{display:flex;gap:7px;overflow:auto;margin:10px 0 15px}.starter-row button,.phase-row button{white-space:nowrap;border:1px solid rgba(148,180,215,.13);background:rgba(255,255,255,.025);color:#9fb2c6;border-radius:999px;padding:9px 12px;font-size:9px;font-weight:800}.starter-row button.active,.phase-row button.active{color:#eafff7;border-color:rgba(102,224,173,.28);background:rgba(102,224,173,.08)}.route-map{position:relative;min-height:560px;border-radius:26px;overflow:hidden;border:1px solid rgba(148,180,215,.13);background:radial-gradient(circle at 50% 45%,rgba(63,145,125,.22),transparent 42%),linear-gradient(145deg,#102c35,#0a192b)}.route-map:before{content:"PALDEA • MAPA DE JORNADA";position:absolute;inset:18px auto auto 18px;font-size:10px;letter-spacing:.14em;color:#a8c6d4}.map-path{position:absolute;left:50%;top:70px;bottom:40px;width:2px;background:linear-gradient(#66e0ad,#4fb5ff,#8d7cff);opacity:.45}.map-node{position:absolute;left:calc(50% - 17px);width:34px;height:34px;border-radius:50%;display:grid;place-items:center;border:2px solid rgba(255,255,255,.28);background:#102b43;color:white;font-size:10px;font-weight:900;box-shadow:0 7px 20px rgba(0,0,0,.3)}.map-node:nth-child(even){margin-left:48px}.map-node:nth-child(odd){margin-left:-48px}.map-full{position:absolute;right:14px;top:14px;z-index:3}.journey-shell.map-fullscreen .journey-top,.journey-shell.map-fullscreen .journey-tabs,.journey-shell.map-fullscreen .journey-hero{display:none}.journey-shell.map-fullscreen{padding:0}.journey-shell.map-fullscreen .journey-body,.journey-shell.map-fullscreen .route-map{max-width:none;width:100%;height:100vh;border:0;border-radius:0;margin:0}.journey-shell.map-fullscreen .route-map{min-height:100vh}@media(max-width:600px){.team-grid{grid-template-columns:repeat(2,1fr)}.route-map{min-height:620px}}
'''
if '/* Journey 1.7 */' not in s:s=s.replace('</style>',css+'\n</style>',1)
# append overrides after 1.6 functions so they win
js=r'''
// Journey 1.7 — progress rings, simplified nav, story teams and route hub.
const SV_ROUTE=[['Cortondo — Katy','gym',15,'Bug'],['Stony Cliff — Klawf','titan',16,'Rock'],['Artazon — Brassius','gym',17,'Grass'],['Open Sky — Bombirdier','titan',19,'Flying'],['Team Star Dark — Giacomo','star',21,'Dark'],['Levincia — Iono','gym',24,'Electric'],['Team Star Fire — Mela','star',27,'Fire'],['Lurking Steel — Orthworm','titan',28,'Steel'],['Cascarrafa — Kofu','gym',30,'Water'],['Team Star Poison — Atticus','star',33,'Poison'],['Medali — Larry','gym',36,'Normal'],['Montenevera — Ryme','gym',42,'Ghost'],['Quaking Earth — Great Tusk / Iron Treads','titan',44,'Ground'],['Alfornada — Tulip','gym',45,'Psychic'],['Glaseado — Grusha','gym',48,'Ice'],['Team Star Fairy — Ortega','star',51,'Fairy'],['False Dragon — Dondozo / Tatsugiri','titan',55,'Dragon'],['Team Star Fighting — Eri','star',56,'Fighting']];
const SV_TEAMS={sprigatito:{early:[906,935,821,940,129,194],mid:[907,936,822,941,130,980],late:[908,936,823,941,130,980]},fuecoco:{early:[909,821,940,129,194,928],mid:[910,822,941,130,980,929],late:[911,823,941,130,980,930]},quaxly:{early:[912,935,821,940,194,928],mid:[913,936,822,941,980,929],late:[914,936,823,941,980,930]}};
state.journey=state.journey||{};state.journey.sv=state.journey.sv||{starter:'sprigatito',phase:'early',done:[]};
function gameProgressV17(g){return activeGameProgress(g)}
const gameCardV16=gameCard;gameCard=function(g){let x=gameCardV16(g),p=gameProgressV17(g);return x.replace('<div class="orb"></div>',`<div class="game-progress-meta"><strong>${p.caught} / ${p.total}</strong>${Math.max(0,p.total-p.caught)} faltando</div><div class="game-progress-ring" style="--gp:${p.pct}%"><div><b>${p.pct}%</b><small>DEX</small></div></div><div class="orb"></div>`)};
function journeySupported(id){return id==='sv'}
const openGameV16=openGame;openGame=function(id){openGameV16(id);setTimeout(()=>{if(!journeySupported(id))return;const m=document.getElementById('modal');if(!m)return;let host=m.querySelector('.modalbox')||m.querySelector('.sheet')||m.firstElementChild;if(host&&!host.querySelector('.journey-launch'))host.insertAdjacentHTML('beforeend',`<button class="btn primary journey-launch" onclick="openJourney('${id}')">◉ Abrir Jornada · Time · Mapa</button>`)},30)};
function closeJourney(){document.getElementById('journeyShell')?.remove()}
function openJourney(id,tab='route'){if(id!=='sv'){premiumToast('Jornada detalhada deste jogo será adicionada em breve');return}closeModal?.();closeJourney();const el=document.createElement('div');el.id='journeyShell';el.className='journey-shell';el.dataset.tab=tab;document.body.appendChild(el);renderJourney(tab)}
function renderJourney(tab){const el=document.getElementById('journeyShell');if(!el)return;el.dataset.tab=tab;const labels={route:'Jornada',team:'Time',map:'Mapa'};el.innerHTML=`<div class="journey-top"><div><div class="eyebrow">Pokémon Scarlet / Violet</div><h2 style="margin:5px 0 0">${labels[tab]}</h2></div><button class="btn" onclick="closeJourney()">Fechar</button></div><div class="journey-tabs">${['route','team','map'].map(t=>`<button class="${t===tab?'active':''}" onclick="renderJourney('${t}')">${labels[t]}</button>`).join('')}</div><div class="journey-body"><div class="journey-hero"><b>Companheiro de jornada</b><p style="color:#93a8c0;font-size:10px;line-height:1.55;margin:7px 0 0">Rota por nível, time de campanha por starter e acompanhamento salvo no aparelho.</p></div>${tab==='route'?journeyRoute():tab==='team'?journeyTeam():journeyMap()}</div>`}
function journeyRoute(){let j=state.journey.sv;return `<div class="route-list">${SV_ROUTE.map((r,i)=>`<div class="route-step ${j.done.includes(i+1)?'done':''}"><div class="num">${j.done.includes(i+1)?'✓':i+1}</div><div><h4>${r[0]}</h4><p>${r[1]==='gym'?'Ginásio':r[1]==='titan'?'Titã':'Team Star'} · ${r[3]} · nível recomendado ${r[2]}</p></div><button class="route-check" onclick="toggleJourneyStep(${i+1})">${j.done.includes(i+1)?'↶':'✓'}</button></div>`).join('')}</div>`}
function toggleJourneyStep(n){let d=state.journey.sv.done,i=d.indexOf(n);i>=0?d.splice(i,1):d.push(n);persist();renderJourney('route')}
function journeyTeam(){let j=state.journey.sv,ids=SV_TEAMS[j.starter][j.phase];return `<div class="starter-row">${['sprigatito','fuecoco','quaxly'].map(x=>`<button class="${j.starter===x?'active':''}" onclick="setJourneyStarter('${x}')">${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div><div class="phase-row">${[['early','Início'],['mid','Mid game'],['late','Late game']].map(x=>`<button class="${j.phase===x[0]?'active':''}" onclick="setJourneyPhase('${x[0]}')">${x[1]}</button>`).join('')}</div><div class="team-grid">${ids.map(id=>`<div class="team-poke" onclick="closeJourney();setTimeout(()=>openPokemon?.(${id}),20)">${pokemonImageHTML(id,'')}<b>#${String(id).padStart(4,'0')}</b><small style="color:#8fa5bc">Ver ficha / build</small></div>`).join('')}</div><p style="font-size:9px;color:#8197ad;line-height:1.5;margin-top:14px">Time voltado à campanha e cobertura da história. A evolução seguinte adicionará movesets, nature, itens e alternativas por versão diretamente em cada ficha.</p>`}
function setJourneyStarter(x){state.journey.sv.starter=x;persist();renderJourney('team')}function setJourneyPhase(x){state.journey.sv.phase=x;persist();renderJourney('team')}
function journeyMap(){return `<div class="route-map"><button class="btn map-full" onclick="toggleJourneyMapFull()">⛶ Tela cheia</button><div class="map-path"></div>${SV_ROUTE.map((r,i)=>`<button class="map-node" style="top:${70+i*27}px" title="${r[0]} · Lv.${r[2]}" onclick="premiumToast('${i+1}. ${r[0]} · Lv.${r[2]}')">${i+1}</button>`).join('')}</div><p style="font-size:9px;color:#8197ad;line-height:1.5">Mapa de Jornada: visual próprio do app para orientar a sequência recomendada. Não substitui o mapa geográfico do jogo.</p>`}
function toggleJourneyMapFull(){document.getElementById('journeyShell')?.classList.toggle('map-fullscreen')}
const androidHandleBackV17=androidHandleBack;androidHandleBack=function(){const j=document.getElementById('journeyShell');if(j){if(j.classList.contains('map-fullscreen')){j.classList.remove('map-fullscreen');return true}closeJourney();return true}return androidHandleBackV17()}
'''
s=s.replace('</body>','<script>'+js+'</script>\n</body>',1)
p.write_text(s,encoding='utf-8')
print('Journey 1.7 applied')
